  const toward0 = wps[0] ?? tp ?? center(tgt);
  const first = sp ?? boundaryPoint(src, toward0);
  const toward1 = wps.length ? wps[wps.length - 1] : first;
  const last = tp ?? boundaryPoint(tgt, toward1);
