  const color = new Uint8Array(n);
  const reversed = new Uint8Array(E.length);
  for (let s = 0; s < n; s++) {
    if (color[s]) continue;
    const stack = [[s, 0]];
    color[s] = 1;
    while (stack.length) {
      const top = stack[stack.length - 1];
      const u = top[0];
      if (top[1] < out[u].length) {
        const k = out[u][top[1]++];
        const v = E[k][1];
        if (color[v] === 1) reversed[k] = 1;
        else if (color[v] === 0) { color[v] = 1; stack.push([v, 0]); }
      } else {
        color[u] = 2;
        stack.pop();
      }
    }
  }
