function connectorSVG(el, route) {
  const pts = route.map((p) => `${num(p[0])},${num(p[1])}`).join(' ');
  const s = el.style ?? {};
  let body = `<polyline points="${pts}" fill="none" stroke="${esc(s.stroke ?? '#000000')}" stroke-width="${num(Number(s.strokeWidth ?? 1))}" marker-end="url(#arrow)"/>`;
