  while ((m = re.exec(xml))) {
    if (m[2] === undefined) continue; // comment / declaration
    if (m[1] === '/') {
      if (stack.length > 1) stack.pop();
      continue;
    }
    const attrs = {};
    const ar = /([\w:.-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
    let a;
    while ((a = ar.exec(m[3]))) attrs[a[1]] = decode(a[2] ?? a[3]);
