}

function walk(node, fn) {
  for (const c of node.children) { fn(c); walk(c, fn); }
}

function parseStyle(s) {
  const out = {};
  for (const part of String(s ?? '').split(';')) {
    if (!part) continue;
    const eq = part.indexOf('=');
    if (eq < 0) out[part] = true;
    else out[part.slice(0, eq)] = part.slice(eq + 1);
