          it.x += op.dx;
          it.y += op.dy;
        }
      }
      return;
    }
    case 'addLayer': {
      const l = op.layer;
      if (!st.layers.has(l.id)) st.layers.set(l.id, clone(l));
      return;
    }
    case 'updateLayer': {
      const l = st.layers.get(op.id);
      if (l) applyPatch(l, op.patch);
      return;
    }
    case 'removeLayer': {
      if (op.id === DEFAULT_LAYER || !st.layers.has(op.id)) return;
