});

$('#back').addEventListener('click', () => {
  disconnect();
  showDashboard();
});

// ---- document session ---------------------------------------------------------
async function openDoc(id) {
  disconnect();
  const meta = await api('GET', `/api/docs/${id}`);
  app.docId = id;
  app.role = meta.role;
  app.doc = createDocument({ id, actor: randomActor() });
  app.seq = 0;
  app.selection = new Set();
