    <label>Opacity <input type="number" min="0" max="1" step="0.1" data-style="opacity" value="${st.opacity ?? 1}"></label>
    <label>Font size <input type="number" min="6" step="1" data-style="fontSize" value="${st.fontSize ?? 14}"></label>
